import { Type, type Static } from "typebox";
import type { AgentTool } from "@earendil-works/pi-agent-core";
import { invalidInputResult, toToolResult } from "../tool-execute.ts";
import { SUGGEST_READING_TOOL } from "../../core/contracts.ts";
import type { ChatStore } from "../../core/ports.ts";

/**
 * suggest_reading — the teacher's OFFER of a reading (docs/readings.md
 * §6.2). SERVER-SIDE, record-only: the call renders an offer card the
 * learner may click to opt in; NOTHING is generated by the call itself
 * (consent and cost stay the learner's). The ack is fixed and slim (the
 * context-diet idiom) and carries the doctrine fence: never assume the
 * learner read anything.
 */

export const SUGGEST_READING_ACK =
	"Offer shown to the learner. Nothing is written unless he opts in, and he may never read it: never build on it, never assume he read it — keep teaching.";

const suggestReadingInput = Type.Object({
	kind: Type.Union([Type.Literal("deep-dive"), Type.Literal("primer"), Type.Literal("recap")], {
		description:
			"deep-dive = the fuller story of one plan node (set planNodeId); primer = the lesson's key terms as definitions; recap = a record of what this session built.",
	}),
	planNodeId: Type.Optional(Type.String({ description: "deep-dive only: the plan node slug, exactly as in plan_init." })),
	title: Type.String({ description: "Short title for the offer card, e.g. 'Where the chain rule comes from'." }),
	why: Type.String({ description: "One sentence to the learner: what the reading would add, outside the lesson's path." }),
});

export interface SuggestReadingContext {
	chatId: string;
	chatStore: Pick<ChatStore, "getChat">;
}

export function readingTools(ctx: SuggestReadingContext): Record<string, AgentTool<any>> {
	const tool: AgentTool<typeof suggestReadingInput> = {
			name: SUGGEST_READING_TOOL,
			label: SUGGEST_READING_TOOL,
			description:
				"OFFER the learner an optional reading — a written document he can open beside the lesson. Nothing is generated unless he clicks; " +
				"he may never read it. Offer when he shows curiosity beyond the lesson's path (a detour worth taking OUTSIDE the session), or a " +
				"primer of terms right after presenting the plan, or a recap near a natural end. Never as a substitute for teaching a step, never " +
				"to defer a question he asked, at most occasionally. Does not end your turn.",
			parameters: suggestReadingInput,
			execute: async (_callId, raw) => {
				const input = raw as Static<typeof suggestReadingInput>;
				const problems: string[] = [];
				if (!input.title.trim()) problems.push("title is empty");
				if (!input.why.trim()) problems.push("why is empty");
				if (input.kind === "deep-dive") {
					if (!input.planNodeId) problems.push("a deep-dive offer needs planNodeId");
					else {
						const known = ctx.chatStore.getChat(ctx.chatId)?.tree?.nodes.map((n) => n.id) ?? [];
						if (!known.includes(input.planNodeId)) {
							problems.push(`planNodeId "${input.planNodeId}" matches no node in this session's plan map`);
						}
					}
				}
				if (problems.length > 0) return invalidInputResult(SUGGEST_READING_TOOL, problems);
				return toToolResult(SUGGEST_READING_ACK);
			},
	};
	return { [SUGGEST_READING_TOOL]: tool };
}
